CREATE TABLE zones (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, deleted_by TEXT REFERENCES user(id));
ALTER TABLE clients ADD COLUMN zone_id TEXT REFERENCES zones(id);
ALTER TABLE clients ADD COLUMN zone_changed_by TEXT REFERENCES user(id);
ALTER TABLE clients ADD COLUMN visit_days_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE routes ADD COLUMN zone_id TEXT REFERENCES zones(id);
CREATE TABLE zone_migration_names (client_id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL);
WITH RECURSIVE names(id,name) AS (SELECT id,trim(replace(replace(replace(replace(zone,char(9),' '),char(10),' '),char(13),' '),char(160),' ')) FROM clients UNION ALL SELECT id,replace(name,'  ',' ') FROM names WHERE instr(name,'  ')>0) INSERT INTO zone_migration_names SELECT id,name,lower(replace(replace(replace(replace(replace(replace(replace(name,'Á','á'),'É','é'),'Í','í'),'Ó','ó'),'Ú','ú'),'Ü','ü'),'Ñ','ñ')) FROM names WHERE name<>'' AND instr(name,'  ')=0;
INSERT INTO zones(id,name,name_key,created_at,updated_at) SELECT lower(hex(randomblob(16))),min(name),name_key,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM zone_migration_names GROUP BY name_key;
UPDATE clients SET zone_id=(SELECT z.id FROM zone_migration_names n JOIN zones z ON z.name_key=n.name_key WHERE n.client_id=clients.id), zone=coalesce((SELECT z.name FROM zone_migration_names n JOIN zones z ON z.name_key=n.name_key WHERE n.client_id=clients.id),''), visit_days_json=(SELECT json_group_array(day) FROM (SELECT DISTINCT CAST(json_extract(s.value,'$.day') AS INTEGER) day FROM json_each(clients.slots_json) s WHERE json_type(s.value,'$.day')='integer' AND json_extract(s.value,'$.day') BETWEEN 0 AND 6 ORDER BY day));
DROP TABLE zone_migration_names;
DROP TRIGGER route_edit_guard;
UPDATE routes SET zone_id=(SELECT min(c.zone_id) FROM visits v JOIN clients c ON c.id=v.client_id WHERE v.route_id=routes.id AND (v.deleted_at IS NULL OR v.deleted_with_route=1) HAVING count(*)>0 AND count(c.zone_id)=count(*) AND count(DISTINCT c.zone_id)=1);
UPDATE routes SET zone_id=NULL WHERE series_id IN (SELECT series_id FROM routes WHERE series_id IS NOT NULL GROUP BY series_id HAVING count(DISTINCT zone_id)>1);
CREATE TRIGGER route_edit_guard BEFORE UPDATE OF name,seller_id,date,series_id,recurrence_json,zone_id ON routes BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM visits WHERE route_id=old.id AND status<>'programada') THEN RAISE(ABORT,'ROUTE_STARTED') END; END;
CREATE INDEX clients_zone_seller ON clients(zone_id,seller_id,active) WHERE deleted_at IS NULL;
CREATE INDEX routes_zone ON routes(zone_id) WHERE deleted_at IS NULL;
CREATE INDEX zones_trash ON zones(deleted_at DESC,id) WHERE deleted_at IS NOT NULL;
CREATE VIEW client_zone_stops AS SELECT v.client_id clientId,v.id visitId,r.id routeId,r.name routeName,v.scheduled_at scheduledAt,r.zone_id routeZoneId,r.seller_id sellerId,NOT EXISTS(SELECT 1 FROM visits other WHERE other.route_id=r.id AND ((other.client_id<>v.client_id AND other.deleted_at IS NULL) OR other.status<>'programada')) archivesRoute FROM visits v JOIN routes r ON r.id=v.route_id WHERE v.deleted_at IS NULL AND v.status='programada' AND r.deleted_at IS NULL AND r.zone_id IS NOT NULL;
CREATE TRIGGER zone_dependencies BEFORE UPDATE OF active,deleted_at ON zones WHEN old.deleted_at IS NULL AND ((old.active=1 AND new.active=0) OR new.deleted_at IS NOT NULL) AND (EXISTS(SELECT 1 FROM clients WHERE zone_id=old.id AND deleted_at IS NULL) OR EXISTS(SELECT 1 FROM routes r JOIN visits v ON v.route_id=r.id WHERE r.zone_id=old.id AND r.deleted_at IS NULL AND v.deleted_at IS NULL AND v.status='programada')) BEGIN SELECT RAISE(ABORT,'ZONE_DEPENDENCIES'); END;
CREATE TRIGGER zone_fts_name AFTER UPDATE OF name ON zones WHEN new.name<>old.name BEGIN UPDATE clients SET zone=new.name WHERE zone_id=new.id; END;
CREATE TRIGGER zone_trash_audit AFTER UPDATE OF deleted_at ON zones WHEN old.deleted_at IS NULL AND new.deleted_at IS NOT NULL BEGIN INSERT INTO audit_log(id,actor_id,action,entity_type,entity_id,created_at) VALUES(lower(hex(randomblob(16))),new.deleted_by,'eliminar','zona',new.id,new.deleted_at); END;
CREATE TRIGGER client_zone_insert BEFORE INSERT ON clients WHEN NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER client_zone_update BEFORE UPDATE OF zone_id ON clients WHEN NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER client_zone_restore BEFORE UPDATE OF deleted_at ON clients WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND new.zone_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER route_zone_insert BEFORE INSERT ON routes WHEN NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER route_zone_update BEFORE UPDATE OF zone_id ON routes WHEN NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER route_zone_restore BEFORE UPDATE OF deleted_at ON routes WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND new.zone_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zones WHERE id=new.zone_id AND active=1 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ZONE_UNAVAILABLE'); END;
CREATE TRIGGER route_visit_zone_insert BEFORE INSERT ON visits WHEN new.route_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM routes r JOIN clients c ON c.id=new.client_id WHERE r.id=new.route_id AND r.zone_id=c.zone_id AND r.seller_id=new.seller_id AND c.seller_id=new.seller_id AND r.deleted_at IS NULL AND c.deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ROUTE_ZONE'); END;
CREATE TRIGGER route_visit_zone_retain BEFORE UPDATE OF route_position ON visits WHEN new.route_id IS NOT NULL AND old.deleted_at IS NULL AND new.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM routes r JOIN clients c ON c.id=new.client_id WHERE r.id=new.route_id AND r.zone_id=c.zone_id AND r.seller_id=new.seller_id AND c.seller_id=new.seller_id AND r.deleted_at IS NULL AND c.deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'ROUTE_ZONE'); END;
CREATE TRIGGER route_visit_zone_restore BEFORE UPDATE OF deleted_at ON visits WHEN old.deleted_at IS NOT NULL AND new.deleted_at IS NULL AND new.route_id IS NOT NULL AND EXISTS(SELECT 1 FROM routes r JOIN clients c ON c.id=new.client_id LEFT JOIN zones z ON z.id=r.zone_id WHERE r.id=new.route_id AND r.zone_id IS NOT NULL AND (r.zone_id IS NOT c.zone_id OR z.deleted_at IS NOT NULL OR z.active<>1)) BEGIN SELECT RAISE(ABORT,'ROUTE_ZONE'); END;
CREATE TRIGGER client_zone_replan AFTER UPDATE OF zone_id ON clients WHEN old.zone_id IS NOT new.zone_id BEGIN UPDATE routes SET deleted_at=new.updated_at,deleted_by=new.zone_changed_by WHERE id IN (SELECT routeId FROM client_zone_stops WHERE clientId=new.id AND routeZoneId<>new.zone_id AND archivesRoute=1); UPDATE visits SET deleted_at=new.updated_at,deleted_by=new.zone_changed_by WHERE id IN (SELECT visitId FROM client_zone_stops WHERE clientId=new.id AND routeZoneId<>new.zone_id); END;
CREATE TRIGGER route_series_zone_insert BEFORE INSERT ON routes WHEN new.series_id IS NOT NULL AND EXISTS(SELECT 1 FROM routes WHERE series_id=new.series_id AND zone_id IS NOT NULL AND zone_id<>new.zone_id) BEGIN SELECT RAISE(ABORT,'ROUTE_SERIES_ZONE'); END;
CREATE TRIGGER route_series_zone_update BEFORE UPDATE OF zone_id ON routes WHEN new.series_id IS NOT NULL AND EXISTS(SELECT 1 FROM routes WHERE series_id=new.series_id AND id<>new.id AND zone_id IS NOT NULL AND zone_id<>new.zone_id) BEGIN SELECT RAISE(ABORT,'ROUTE_SERIES_ZONE'); END;
